"""Simulated daily telemetry for one crew member. Not real crew data."""

import json
from pathlib import Path

import numpy as np

# Plausible per-person mean and day-to-day noise (sd) for each field. Simulated values.
PROFILE = {
    "heart_rate_bpm": (62.0, 2.5),
    "hrv_rmssd_ms": (55.0, 2.5),
    "spo2_pct": (98.0, 0.4),
    "core_temp_c": (36.8, 0.1),
    "sleep_hours": (7.0, 0.3),
    "exercise_min": (120.0, 8.0),
    "reaction_ms": (280.0, 10.0),
    "mood_1to5": (4.0, 0.2),  # daily average of check-ins, so not an integer
}

NOTE = (
    "Synthetic telemetry generated by src/baseline/fixtures.py. Not real crew data. "
    "Plain Gaussian noise around fixed per-person means; nothing is filtered or redrawn."
)


def make_fixture(seed: int, days: int = 30, anomaly_start: int | None = 27) -> list[dict]:
    rng = np.random.default_rng(seed)
    rows = [
        {"day": day, **{f: round(float(mean + rng.normal(0, sd)), 2) for f, (mean, sd) in PROFILE.items()},
         "near_vision_ok": True}
        for day in range(1, days + 1)
    ]

    if anomaly_start is not None:
        for row in rows:
            d = row["day"]
            effect = 1.0 if anomaly_start <= d <= anomaly_start + 2 else 0.5 if d == anomaly_start + 3 else 0.0
            row["hrv_rmssd_ms"] = round(row["hrv_rmssd_ms"] * (1 - 0.25 * effect), 2)
            row["sleep_hours"] = round(row["sleep_hours"] * (1 - 0.30 * effect), 2)
            row["reaction_ms"] = round(row["reaction_ms"] * (1 + 0.20 * effect), 2)
            row["mood_1to5"] = round(row["mood_1to5"] - 1.0 * effect, 2)
    return rows


def write_fixtures(out_dir: str = "data/fixtures") -> None:
    out = Path(out_dir)
    for name, anomaly_start in [("crew_a_anomaly.json", 27), ("crew_a_clean.json", None)]:
        doc = {"source": "simulated", "note": NOTE, "rows": make_fixture(7, anomaly_start=anomaly_start)}
        (out / name).write_text(json.dumps(doc, indent=2) + "\n")
